import csv,sqlite3
with open('csv/atom.csv') as f:
    atoms=list(csv.DictReader(f))
at_by_mol={}
for a in atoms:
    m=a['molecule_id']
    if m not in at_by_mol:
        at_by_mol[m]=[]
    at_by_mol[m].append(a)
with sqlite3.connect('db/bond.db') as con:
    cur=con.cursor()
    cur.execute("SELECT DISTINCT molecule_id FROM bond WHERE bond_type='#'")
    triple_mol={r[0] for r in cur.fetchall()}
mols_pbr=set()
for m in triple_mol:
    has_pbr=False
    for a in at_by_mol[m]:
        if a['element']=='p' or a['element']=='br':
            has_pbr=True
            break
    if has_pbr:
        mols_pbr.add(m)
print('Mol with triple+ p/br:',mols_pbr)
total=sum(len(at_by_mol[m]) for m in mols_pbr)
print('Total atoms:',total)

